const PHYSICS_DP = [{"id": "3.1.1.1", "unit": 3, "topic": "T1 - Gravity and motion", "subtopic": "S1 - Projectile Motion", "code": "3.1.1.1", "descriptor": "Apply vector analysis to resolve a vector into two perpendicular components.", "graphical": false, "needsExplanation": false, "modelAnswer": null}, {"id": "3.1.1.2", "unit": 3, "topic": "T1 - Gravity and motion", "subtopic": "S1 - Projectile Motion", "code": "3.1.1.2", "descriptor": "Solve vector problems by resolving vectors into components, adding or subtracting the components and recombining them to determine the resultant vector.", "graphical": false, "needsExplanation": false, "modelAnswer": null}, {"id": "3.1.1.3", "unit": 3, "topic": "T1 - Gravity and motion", "subtopic": "S1 - Projectile Motion", "code": "3.1.1.3", "descriptor": "Describe how horizontal and vertical components of a velocity vector are independent of each other.", "graphical": false, "needsExplanation": true, "modelAnswer": ["Horizontal and vertical motion are independent because gravity acts only vertically — there is no horizontal force acting on the projectile (ignoring air resistance), so the two components can be treated as two separate, simultaneous one-dimensional motions.", "The horizontal velocity component stays constant throughout the flight, since there is zero horizontal acceleration.", "The vertical velocity component changes uniformly, accelerating at g = 9.8 m/s² downward, exactly as it would for an object simply dropped or thrown straight up.", "Both components share the same time of flight — each is analysed with the standard SUVAT equations using that common time, then recombined (via vector addition) to give the resultant velocity or displacement at any instant."]}, {"id": "3.1.1.4", "unit": 3, "topic": "T1 - Gravity and motion", "subtopic": "S1 - Projectile Motion", "code": "3.1.1.4", "descriptor": "Solve problems involving projectile motion in the absence of drag effects using equations on the RHS", "graphical": true, "needsExplanation": false, "modelAnswer": null}, {"id": "3.1.1.5", "unit": 3, "topic": "T1 - Gravity and motion", "subtopic": "S1 - Projectile Motion", "code": "3.1.1.5", "descriptor": "Interpret data relating to the horizontal distance travelled by an object projected at various angles from the horizontal.", "graphical": true, "needsExplanation": false, "modelAnswer": null}, {"id": "3.1.2.1", "unit": 3, "topic": "T1 - Gravity and motion", "subtopic": "S2 - Inclined planes and circular motion", "code": "3.1.2.1", "descriptor": "Solve problems involving force due to gravity (weight) and mass using Fg=mg", "graphical": true, "needsExplanation": false, "modelAnswer": null}, {"id": "3.1.2.2", "unit": 3, "topic": "T1 - Gravity and motion", "subtopic": "S2 - Inclined planes and circular motion", "code": "3.1.2.2", "descriptor": "Describe the concept of normal force.", "graphical": false, "needsExplanation": true, "modelAnswer": ["Normal force (F_N) is the contact force a surface exerts on an object, always directed perpendicular (normal) to that surface.", "It is a reaction force: as the object presses into the surface, the surface pushes back with equal and opposite force (Newton's third law pair), preventing the object from passing through it.", "Its magnitude is whatever is needed to balance the perpendicular forces acting into the surface — on a flat horizontal surface with no other vertical forces F_N = mg; on an incline F_N = mg cos θ; it can also be reduced or increased by an additional applied force with a component into/out of the surface."]}, {"id": "3.1.2.3", "unit": 3, "topic": "T1 - Gravity and motion", "subtopic": "S2 - Inclined planes and circular motion", "code": "3.1.2.3", "descriptor": "Describe the forces acting on an object on an inclined plane (e.g. force due to gravity, normal force, tension, frictional force and applied force) through the use of free-body diagrams.", "graphical": false, "needsExplanation": true, "modelAnswer": ["A free-body diagram shows only the forces acting ON the object (drawn as arrows from a single point, usually its centre), not forces the object exerts on other things.", "For an object on an incline, relevant forces typically include: weight (Fg = mg, straight down), normal force (perpendicular to the incline surface), friction (parallel to the surface, opposing sliding or the tendency to slide), tension (along a string/rope, if present), and any other applied force.", "Weight is usually resolved into two components relative to the incline: mg sin θ acting down the slope (parallel to the surface) and mg cos θ acting into the slope (perpendicular to the surface) — these replace the single weight vector for analysis.", "Arrow lengths should roughly reflect relative magnitude, each force should be clearly labelled, and the net/resultant force (if asked for) is found by summing components along and perpendicular to the incline."]}, {"id": "3.1.2.4", "unit": 3, "topic": "T1 - Gravity and motion", "subtopic": "S2 - Inclined planes and circular motion", "code": "3.1.2.4", "descriptor": "Determine the net force acting on an object on an inclined plane using vector analysis.", "graphical": false, "needsExplanation": false, "modelAnswer": null}, {"id": "3.1.2.5", "unit": 3, "topic": "T1 - Gravity and motion", "subtopic": "S2 - Inclined planes and circular motion", "code": "3.1.2.5", "descriptor": "Describe the concept of uniform circular motion.", "graphical": false, "needsExplanation": true, "modelAnswer": ["Uniform circular motion is motion in a circular path at constant speed, meaning the magnitude of velocity is constant but its direction is continuously changing.", "Angular velocity (ω) is also constant, and speed relates to it by v = ωr.", "Because the direction of velocity is always changing, the object has a non-zero acceleration (centripetal acceleration), directed toward the centre of the circle, even though speed itself does not change."]}, {"id": "3.1.2.6", "unit": 3, "topic": "T1 - Gravity and motion", "subtopic": "S2 - Inclined planes and circular motion", "code": "3.1.2.6", "descriptor": "Describe the concepts of average speed and period.", "graphical": false, "needsExplanation": true, "modelAnswer": ["Average speed = total distance travelled ÷ total time taken — a scalar quantity, distinct from average velocity (which is displacement ÷ time).", "Period (T) is the time taken to complete one full revolution or cycle of circular (or other repeating) motion, measured in seconds.", "Frequency (f) is the number of revolutions per second, f = 1/T.", "For uniform circular motion, average speed = distance for one revolution ÷ period = circumference ÷ T = 2πr/T."]}, {"id": "3.1.2.7", "unit": 3, "topic": "T1 - Gravity and motion", "subtopic": "S2 - Inclined planes and circular motion", "code": "3.1.2.7", "descriptor": "Solve problems involving objects undergoing uniform circular motion at a constant speed using v=(2(pi)r)/T and ac = v^2/r", "graphical": true, "needsExplanation": false, "modelAnswer": null}, {"id": "3.1.2.8", "unit": 3, "topic": "T1 - Gravity and motion", "subtopic": "S2 - Inclined planes and circular motion", "code": "3.1.2.8", "descriptor": "Describe the concepts of centripetal acceleration and centripetal force.", "graphical": false, "needsExplanation": true, "modelAnswer": ["Centripetal acceleration is the acceleration directed toward the centre of a circular path, responsible for continuously changing the direction of velocity; its magnitude is ac = v²/r = ω²r.", "Centripetal force is the net (resultant) force required to produce this acceleration; it always points toward the centre, with magnitude Fc = mv²/r = mω²r.", "Centripetal force is not a separate, new type of force in its own right — it is the name given to whatever combination of real forces (tension, gravity, normal force, friction, etc.) supplies the net inward force in a given situation.", "Because it is always perpendicular to velocity, centripetal force does no work on the object, which is why speed stays constant in uniform circular motion even though the object is accelerating."]}, {"id": "3.1.2.9", "unit": 3, "topic": "T1 - Gravity and motion", "subtopic": "S2 - Inclined planes and circular motion", "code": "3.1.2.9", "descriptor": "Solve problems involving forces acting on objects in uniform circular motion using Fc = Fnet = mv^2/r", "graphical": true, "needsExplanation": false, "modelAnswer": null}, {"id": "3.1.3.1", "unit": 3, "topic": "T1 - Gravity and motion", "subtopic": "S3 - Orbital Mechanics", "code": "3.1.3.1", "descriptor": "Describe the Law of Universal Gravitation.", "graphical": false, "needsExplanation": true, "modelAnswer": ["The Law of Universal Gravitation states that every point mass in the universe attracts every other point mass with a force directed along the line joining their centres.", "The force is directly proportional to the product of the two masses and inversely proportional to the square of the distance between their centres: F = GMm/r².", "G is the universal gravitational constant (6.67 × 10⁻¹¹ N m² kg⁻²), the same for all masses everywhere.", "The force is always attractive, and by Newton's third law each mass exerts an equal and opposite force on the other."]}, {"id": "3.1.3.2", "unit": 3, "topic": "T1 - Gravity and motion", "subtopic": "S3 - Orbital Mechanics", "code": "3.1.3.2", "descriptor": "Solve problems involving the magnitude of the gravitational force between two masses using F = (GMm)/r^2", "graphical": true, "needsExplanation": false, "modelAnswer": null}, {"id": "3.1.3.3", "unit": 3, "topic": "T1 - Gravity and motion", "subtopic": "S3 - Orbital Mechanics", "code": "3.1.3.3", "descriptor": "Describe the concept of gravitational fields.", "graphical": false, "needsExplanation": true, "modelAnswer": ["A gravitational field is the region of space around a mass in which another mass experiences a force of gravitational attraction.", "Gravitational field strength (g) at a point is defined as the gravitational force experienced per unit mass placed at that point: g = F/m = GM/r², measured in N/kg (numerically equivalent to m/s²).", "Field strength decreases with the square of distance from the source mass and is a vector, always directed toward the mass creating the field.", "Fields are represented with field lines pointing radially inward toward the mass; line density (spacing) represents relative field strength — closer lines mean a stronger field."]}, {"id": "3.1.3.4", "unit": 3, "topic": "T1 - Gravity and motion", "subtopic": "S3 - Orbital Mechanics", "code": "3.1.3.4", "descriptor": "Solve problems involving the gravitational field strength at a distance from an object using  g = F/m = (GM)/r^2", "graphical": true, "needsExplanation": false, "modelAnswer": null}, {"id": "3.1.3.5", "unit": 3, "topic": "T1 - Gravity and motion", "subtopic": "S3 - Orbital Mechanics", "code": "3.1.3.5", "descriptor": "State the three laws of planetary motion.", "graphical": false, "needsExplanation": true, "modelAnswer": ["1st law (Law of Orbits/Ellipses): planets orbit the Sun in elliptical paths, with the Sun located at one focus of the ellipse (not the centre).", "2nd law (Law of Areas): a line joining a planet to the Sun sweeps out equal areas in equal time intervals — so a planet moves fastest at its closest approach (perihelion) and slowest at its furthest point (aphelion).", "3rd law (Law of Periods): the square of a planet's orbital period is directly proportional to the cube of its average orbital radius (semi-major axis): T² ∝ r³, with the same constant of proportionality for all planets orbiting the same star."]}, {"id": "3.1.3.6", "unit": 3, "topic": "T1 - Gravity and motion", "subtopic": "S3 - Orbital Mechanics", "code": "3.1.3.6", "descriptor": "Describe the relationship between the Law of Universal Gravitation and uniform circular motion and recognise this as the third law of planetary motion.", "graphical": false, "needsExplanation": true, "modelAnswer": ["For a planet in a circular orbit, gravity supplies the centripetal force keeping it in that orbit, so the two expressions for force can be set equal: GMm/r² = mv²/r, or in terms of period, GMm/r² = m(4π²r)/T².", "Rearranging either form gives T²/r³ = 4π²/(GM) — a constant value for any object orbiting the same central mass M, independent of the orbiting object's own mass.", "This T² ∝ r³ relationship is precisely Kepler's third law, so the third law of planetary motion is the mathematical result of combining Newton's Law of Universal Gravitation with the equations of uniform circular motion.", "This also shows Kepler's empirically-derived law and Newton's force law are describing the same underlying physics, unifying the two frameworks."]}, {"id": "3.1.3.7", "unit": 3, "topic": "T1 - Gravity and motion", "subtopic": "S3 - Orbital Mechanics", "code": "3.1.3.7", "descriptor": "Solve problems involving the third law of planetary motion using Ta^2/ra^3 = Tb^2/rb^3 = 4(PI)^2/(GM)", "graphical": true, "needsExplanation": false, "modelAnswer": null}, {"id": "3.2.1.1", "unit": 3, "topic": "T2 - Electromagnetism", "subtopic": "S1 - Electrostatics", "code": "3.2.1.1", "descriptor": "Describe Coulomb’s Law.", "graphical": false, "needsExplanation": true, "modelAnswer": ["Coulomb's Law states that the electrostatic force between two point charges is directly proportional to the product of the magnitudes of the charges and inversely proportional to the square of the distance between them.", "F = kq₁q₂/r², where k is Coulomb's constant (≈ 8.99 × 10⁹ N m²/C⁻²), often also written as 1/(4πε₀).", "Like charges (same sign) repel; unlike charges (opposite sign) attract; the force in each case acts along the straight line joining the two charges, and each charge experiences an equal and opposite force (Newton's third law)."]}, {"id": "3.2.1.2", "unit": 3, "topic": "T2 - Electromagnetism", "subtopic": "S1 - Electrostatics", "code": "3.2.1.2", "descriptor": "Solve problems using Coulomb's Law Equation", "graphical": true, "needsExplanation": false, "modelAnswer": null}, {"id": "3.2.1.3", "unit": 3, "topic": "T2 - Electromagnetism", "subtopic": "S1 - Electrostatics", "code": "3.2.1.3", "descriptor": "Describe the concepts of electric fields, electric field strength and electrical potential energy.", "graphical": false, "needsExplanation": true, "modelAnswer": ["Electric field: the region of space around a charge (or charges) in which another charge experiences an electrostatic force; conventionally represented by field lines pointing away from positive charges and toward negative charges.", "Electric field strength (E): the electrostatic force experienced per unit positive charge at a point, E = F/q, measured in N/C (equivalently V/m); for an isolated point charge, E = kQ/r².", "Field strength is a vector quantity — its direction is the direction a small positive test charge would be pushed, and its magnitude decreases with the square of distance from a point charge.", "Electric potential energy: the energy a charge possesses due to its position within an electric field, equal to the work done (by an external agent) to move the charge from a reference point (often infinity) to that position; for two point charges, Ep = kq₁q₂/r."]}, {"id": "3.2.1.4", "unit": 3, "topic": "T2 - Electromagnetism", "subtopic": "S1 - Electrostatics", "code": "3.2.1.4", "descriptor": "Solve problems involving electric field strength using equation", "graphical": true, "needsExplanation": false, "modelAnswer": null}, {"id": "3.2.1.5", "unit": 3, "topic": "T2 - Electromagnetism", "subtopic": "S1 - Electrostatics", "code": "3.2.1.5", "descriptor": "Solve problems involving the work done when an electric charge is moved in an electric field using equation", "graphical": true, "needsExplanation": false, "modelAnswer": null}, {"id": "3.2.2.1", "unit": 3, "topic": "T2 - Electromagnetism", "subtopic": "S2 - Magnetic fields", "code": "3.2.2.1", "descriptor": "Describe the concept of a magnetic field.", "graphical": false, "needsExplanation": true, "modelAnswer": ["A magnetic field is the region of space around a magnet, a moving electric charge, or a current-carrying conductor, in which another moving charge or magnetic material experiences a magnetic force.", "A moving electric charge itself produces a magnetic field around it — this is the underlying source of all magnetic fields, including those of permanent magnets, which arise from the alignment of many atomic-scale moving charges (electron spin/orbital motion).", "Represented using field lines that point from a magnet's north pole to its south pole outside the magnet, forming continuous closed loops (they have no beginning or end); line density indicates relative field strength.", "Field strength is measured by the magnetic flux density B, in tesla (T); for a long straight current-carrying wire, B is directly proportional to the current I and inversely proportional to the distance r from the wire (B = μ₀I / (2πr))."]}, {"id": "3.2.2.2", "unit": 3, "topic": "T2 - Electromagnetism", "subtopic": "S2 - Magnetic fields", "code": "3.2.2.2", "descriptor": "Sketch magnetic field lines due to a moving electric charge, electric currents and magnets.", "graphical": false, "needsExplanation": false, "modelAnswer": null}, {"id": "3.2.2.3", "unit": 3, "topic": "T2 - Electromagnetism", "subtopic": "S2 - Magnetic fields", "code": "3.2.2.3", "descriptor": "Describe the generation of a magnetic field from a moving electric charge.", "graphical": false, "needsExplanation": true, "modelAnswer": ["A moving electric charge generates a magnetic field around it; since an electric current is simply charge in motion, a current-carrying conductor is also surrounded by a magnetic field.", "For a long straight current-carrying wire, the field forms concentric circles centred on the wire, in planes perpendicular to it; field direction is given by the right-hand grip rule (thumb in the direction of conventional current, fingers curl in the direction of B).", "Field strength around a straight wire is directly proportional to the current (B ∝ I) and inversely proportional to the perpendicular distance from the wire (B ∝ 1/r); formally B = μ₀I / (2πr).", "A stationary charge produces only an electric field; it is specifically the charge's motion that gives rise to the accompanying magnetic field."]}, {"id": "3.2.2.4", "unit": 3, "topic": "T2 - Electromagnetism", "subtopic": "S2 - Magnetic fields", "code": "3.2.2.4", "descriptor": "Solve problems involving the magnitude and direction of magnetic fields around a straight electric current-carrying wire and inside a solenoid using equations on RHS", "graphical": true, "needsExplanation": false, "modelAnswer": null}, {"id": "3.2.2.5", "unit": 3, "topic": "T2 - Electromagnetism", "subtopic": "S2 - Magnetic fields", "code": "3.2.2.5", "descriptor": "Describe the force experienced by electric current-carrying conductors and moving electric charges when placed in a magnetic field.", "graphical": false, "needsExplanation": true, "modelAnswer": ["A current-carrying conductor (or a single moving charge) placed in an external magnetic field experiences a force whenever its velocity/current direction has a component perpendicular to the field.", "For a single moving charge: F = qvB sin θ; for a straight current-carrying wire: F = BIL sin θ, where θ is the angle between the current (or velocity) direction and the magnetic field direction.", "The force is a maximum when the current/velocity is perpendicular to the field (θ = 90°) and zero when it is parallel or antiparallel to the field (θ = 0° or 180°).", "The direction of the force is given by the right-hand slap/palm rule (or the vector relation F = qv × B, or F = IL × B): the force is always perpendicular to both the field and the current/velocity direction."]}, {"id": "3.2.2.6", "unit": 3, "topic": "T2 - Electromagnetism", "subtopic": "S2 - Magnetic fields", "code": "3.2.2.6", "descriptor": "Solve problems involving the magnetic force on an electric current-carrying wire and moving charge in a magnetic field using equations on RHS", "graphical": true, "needsExplanation": false, "modelAnswer": null}, {"id": "3.2.2.7", "unit": 3, "topic": "T2 - Electromagnetism", "subtopic": "S2 - Magnetic fields", "code": "3.2.2.7", "descriptor": "Interpret data relating to the force acting on a conductor in a magnetic field.", "graphical": true, "needsExplanation": true, "modelAnswer": ["Identify the variables plotted (e.g. force vs current, or force vs conductor length) and describe the relationship shown — typically linear/directly proportional, consistent with F = BIL sin θ at fixed B, L and θ.", "Determine the gradient of a linear graph and relate it to the physical quantity it represents (e.g. the gradient of a force–current graph equals BL sin θ, so B can be extracted if L and θ are known).", "Use the graph (interpolation/extrapolation, or the gradient) to calculate an unknown quantity such as magnetic flux density B, and comment on the reliability of the result (line of best fit, scatter of data points, size of uncertainty).", "Note any limitations of the data or method — e.g. a non-zero y-intercept suggesting a systematic error, or a restricted range of current values tested."]}, {"id": "3.2.2.8", "unit": 3, "topic": "T2 - Electromagnetism", "subtopic": "S2 - Magnetic fields", "code": "3.2.2.8", "descriptor": "Interpret data relating to the strength of a magnet at various distances.", "graphical": true, "needsExplanation": true, "modelAnswer": ["Describe the trend shown: magnetic field strength (or force on a test object) decreases as distance from the magnet increases, typically following an inverse-square or inverse-cube relationship depending on the magnet geometry and setup.", "Recognise the relationship is non-linear on a field-strength-vs-distance graph — plotting field strength against 1/r² (or 1/r³) can linearise the data and confirm the specific relationship.", "Use the graph to interpolate or extrapolate values (with appropriate caution about extrapolating beyond the measured range), and discuss experimental limitations, such as difficulty accurately measuring field strength very close to the magnet, or background/Earth's magnetic field affecting readings."]}, {"id": "3.2.3.1", "unit": 3, "topic": "T2 - Electromagnetism", "subtopic": "S3 - Electromagnetic induction", "code": "3.2.3.1", "descriptor": "Describe the concepts of magnetic flux, magnetic flux density, electromagnetic induction, electromotive force (EMF), Faraday’s Law and Lenz’s Law.", "graphical": false, "needsExplanation": true, "modelAnswer": ["Magnetic flux (Φ): a measure of the total amount of magnetic field passing through a given area, Φ = B·A·cos θ, where θ is the angle between the field and the normal to the area; measured in weber (Wb).", "Magnetic flux density (B): the strength of the magnetic field per unit area (i.e. flux per unit area presented perpendicular to the field), measured in tesla (T); B = Φ/A when the field is perpendicular to the area.", "Electromagnetic induction: the process by which a changing magnetic flux through a conductor or coil generates (induces) an EMF, and — if the conductor forms part of a closed circuit — a current.", "Electromotive force (EMF, ε): the induced potential difference that drives current around the circuit as a result of the changing flux (measured in volts, like any other voltage).", "Faraday's Law: the magnitude of the induced EMF is proportional to the rate of change of magnetic flux linkage, ε = −N(ΔΦ/Δt), where N is the number of turns in the coil.", "Lenz's Law: the induced current flows in the direction that opposes the change in flux that produced it — this is the physical meaning of the negative sign in Faraday's Law, and is itself a statement of conservation of energy."]}, {"id": "3.2.3.2", "unit": 3, "topic": "T2 - Electromagnetism", "subtopic": "S3 - Electromagnetic induction", "code": "3.2.3.2", "descriptor": "Solve problems involving the magnetic flux in an electric current-carrying loop using equation on RHS", "graphical": true, "needsExplanation": false, "modelAnswer": null}, {"id": "3.2.3.3", "unit": 3, "topic": "T2 - Electromagnetism", "subtopic": "S3 - Electromagnetic induction", "code": "3.2.3.3", "descriptor": "Describe the process of inducing an EMF across a moving conductor in a magnetic field.", "graphical": false, "needsExplanation": true, "modelAnswer": ["When a conductor moves through a magnetic field (or the field changes relative to a stationary conductor), free (mobile) charges within the conductor experience a magnetic force, F = qvB, due to their motion relative to the field.", "This force pushes positive and negative charges toward opposite ends of the conductor, building up a charge separation and therefore a potential difference along its length — this is the motional EMF.", "For a straight rod of length L moving with velocity v perpendicular to a uniform field B, the induced EMF is ε = BLv.", "If the conductor is part of a closed circuit, this EMF drives an induced current around the circuit, in the direction predicted by Lenz's Law."]}, {"id": "3.2.3.4", "unit": 3, "topic": "T2 - Electromagnetism", "subtopic": "S3 - Electromagnetic induction", "code": "3.2.3.4", "descriptor": "Explain how Lenz’s Law is consistent with the principle of conservation of energy.", "graphical": false, "needsExplanation": true, "modelAnswer": ["Lenz's Law states the induced current flows in the direction that opposes the change in flux that produced it — for example, opposing the motion of a magnet being pushed into a coil, or opposing an increasing/decreasing flux.", "Because the induced current opposes the change, an external agent must do mechanical work (apply a force over a distance, e.g. to keep moving the magnet or conductor) to maintain that change against the opposing induced magnetic force.", "This mechanical work done by the external agent is exactly what is converted into electrical energy (the induced EMF driving current) — so energy is transformed from mechanical to electrical form, not created.", "This is consistent with — and is essentially a restatement of — the principle of conservation of energy: electrical energy only appears because an equivalent amount of mechanical (or other) energy is put in and converted, not generated from nothing."]}, {"id": "3.2.3.5", "unit": 3, "topic": "T2 - Electromagnetism", "subtopic": "S3 - Electromagnetic induction", "code": "3.2.3.5", "descriptor": "Explain how transformers work in terms of Faraday’s Law and electromagnetic induction.", "graphical": false, "needsExplanation": true, "modelAnswer": ["A transformer consists of two separate coils (primary and secondary) wound around a shared iron core, with no direct electrical (conductive) connection between them.", "By Faraday's Law, an induced EMF is produced whenever the magnetic flux linking a circuit changes, and the size of that EMF is proportional to the rate of change of flux linkage.", "Because the current in the primary coil is alternating, it produces a magnetic field that is constantly changing in magnitude and direction, so the magnetic flux threading the core is also constantly changing.", "The iron core channels this changing flux through the secondary coil; since the flux linking the secondary coil is changing, Faraday's Law means an alternating EMF is induced in it — this is why a voltage appears in the secondary circuit even though it is not directly wired to the primary.", "The ratio of secondary to primary voltage equals the ratio of the number of turns on each coil: Vs/Vp = Ns/Np — more turns on the secondary than primary (Ns > Np) steps voltage up; fewer turns (Ns < Np) steps voltage down.", "For an ideal transformer, power is conserved (Vp Ip = Vs Is), so stepping voltage up correspondingly steps current down, and vice versa."]}, {"id": "3.2.3.6", "unit": 3, "topic": "T2 - Electromagnetism", "subtopic": "S3 - Electromagnetic induction", "code": "3.2.3.6", "descriptor": "Solve problems involving electromagnetic induction using equations on RHS", "graphical": true, "needsExplanation": false, "modelAnswer": null}, {"id": "3.2.3.7", "unit": 3, "topic": "T2 - Electromagnetism", "subtopic": "S3 - Electromagnetic induction", "code": "3.2.3.7", "descriptor": "Describe the concept of an electromagnetic wave.", "graphical": false, "needsExplanation": true, "modelAnswer": ["An electromagnetic wave is a transverse wave made up of oscillating electric and magnetic fields, perpendicular to each other and both perpendicular to the direction the wave travels.", "Unlike mechanical waves, it requires no medium and can travel through a vacuum, at speed c (≈ 3.0 × 10⁸ m/s in a vacuum).", "It is produced whenever an electric charge accelerates (e.g. oscillates), and carries energy from the source outward.", "The electromagnetic spectrum spans a continuous range of frequencies/wavelengths (radio, microwave, infrared, visible, ultraviolet, X-ray, gamma), all travelling at the same speed c in a vacuum, related by c = fλ."]}, {"id": "3.2.3.8", "unit": 3, "topic": "T2 - Electromagnetism", "subtopic": "S3 - Electromagnetic induction", "code": "3.2.3.8", "descriptor": "Explain the relationship between oscillating electric charges and electromagnetic waves.", "graphical": false, "needsExplanation": true, "modelAnswer": ["An oscillating (accelerating) electric charge produces an oscillating electric field around it.", "Because this electric field is continuously changing, it in turn generates an oscillating magnetic field (a changing E field produces a B field).", "This oscillating magnetic field is itself changing, so it generates an oscillating electric field further out — the two fields continuously regenerate and sustain each other.", "This mutual, self-propagating regeneration of perpendicular oscillating E and B fields is what constitutes the electromagnetic wave, which radiates outward from the source at speed c, carrying energy independently of the original charge."]}, {"id": "4.1.1.1", "unit": 4, "topic": "T1 - Special Relativity", "subtopic": "S1 - Special Relativity", "code": "4.1.1.1", "descriptor": "Describe observations of natural phenomena that cannot be explained by classical physics, e.g. the presence of muons in the atmosphere and the momentum of high speed particles in particle accelerators.", "graphical": false, "needsExplanation": true, "modelAnswer": ["Muons created by cosmic ray collisions high in the atmosphere have a very short half-life, so classical (Newtonian) mechanics predicts that almost all of them should decay before travelling far enough to reach the Earth's surface.", "Far more muons are actually detected at ground level than this classical calculation predicts. From Earth's (the observer's) frame of reference, this is explained by relativistic time dilation: the fast-moving muon's internal decay 'clock' runs slow, extending its measured half-life enough for a much larger fraction to survive the trip down.", "Equivalently, from the muon's own frame of reference, its half-life is unchanged (it is not moving relative to itself), but instead it experiences the depth of the atmosphere as length-contracted — a much shorter distance to travel — so more muons survive to reach the ground within their normal half-life. Both descriptions agree on the outcome, illustrating that time dilation and length contraction are two frame-dependent perspectives on the same relativistic effect.", "In particle accelerators, particles travelling at speeds close to c gain momentum and energy far in excess of what classical mechanics (p = mv) predicts; their measured behaviour instead matches the relativistic expressions for momentum and energy (p = γm₀v, E = γm₀c²).", "Both observations show classical mechanics accurately describes motion at everyday speeds but breaks down at speeds close to c, where special relativity is needed."]}, {"id": "4.1.1.2", "unit": 4, "topic": "T1 - Special Relativity", "subtopic": "S1 - Special Relativity", "code": "4.1.1.2", "descriptor": "Describe the concepts of frame of reference and inertial frame of reference.", "graphical": false, "needsExplanation": true, "modelAnswer": ["A frame of reference is a coordinate system — with a defined origin, set of axes, and clock — from which the position, motion and timing of events are measured and described.", "An inertial frame of reference is one that is not accelerating: it is either at rest or moving at constant velocity, so an object with no net force on it moves at constant velocity within that frame (Newton's first law holds).", "A non-inertial frame is one that is accelerating (speeding up, slowing down, or turning); Newton's first law does not hold within it without introducing fictitious forces.", "A key postulate of special relativity is that the laws of physics take the same form in every inertial frame of reference — no inertial frame is preferred over another."]}, {"id": "4.1.1.3", "unit": 4, "topic": "T1 - Special Relativity", "subtopic": "S1 - Special Relativity", "code": "4.1.1.3", "descriptor": "State the two postulates of special relativity.", "graphical": false, "needsExplanation": true, "modelAnswer": ["1. The laws of physics are the same (invariant) in all inertial reference frames — no experiment performed entirely within an inertial frame can determine whether that frame is 'moving' or 'at rest'.", "2. The speed of light in a vacuum has the same value (c) for all observers in inertial frames, regardless of the motion of the light source or the observer measuring it."]}, {"id": "4.1.1.4", "unit": 4, "topic": "T1 - Special Relativity", "subtopic": "S1 - Special Relativity", "code": "4.1.1.4", "descriptor": "Explain how motion can only be measured relative to an observer.", "graphical": false, "needsExplanation": true, "modelAnswer": ["There is no absolute or universal frame of reference against which the 'true' motion of an object could be measured — every inertial frame is equally valid for describing physics.", "As a result, velocity (and therefore whether something is 'moving') can only be stated relative to a chosen reference frame or observer — the same object can correctly be described as at rest in one frame and moving in another.", "For example, a passenger seated on a moving train is at rest relative to the train (and to another passenger) but moving relative to an observer standing on the ground."]}, {"id": "4.1.1.5", "unit": 4, "topic": "T1 - Special Relativity", "subtopic": "S1 - Special Relativity", "code": "4.1.1.5", "descriptor": "Explain the concept of simultaneity.", "graphical": false, "needsExplanation": true, "modelAnswer": ["Simultaneity describes two (or more) events happening at the same time.", "In special relativity, simultaneity is relative rather than absolute: two spatially separated events judged to happen at the same time by one inertial observer will generally not be judged simultaneous by a different observer moving relative to the first.", "This occurs because light from each event takes a finite time to travel to an observer, and the constant speed of light means observers in relative motion disagree on when light from each event reaches them, and hence on the order/timing of distant events.", "Events that occur at the same place as well as the same time are simultaneous for all observers — relativity of simultaneity specifically affects events separated in space."]}, {"id": "4.1.1.6", "unit": 4, "topic": "T1 - Special Relativity", "subtopic": "S1 - Special Relativity", "code": "4.1.1.6", "descriptor": "Describe the consequences of the constant speed of light in a vacuum, e.g. time dilation and length contraction.", "graphical": false, "needsExplanation": true, "modelAnswer": ["Because the speed of light must be measured as the same constant value c by every inertial observer, observers in relative motion must instead measure different values for time intervals and lengths between the same two events, in order to keep c consistent.", "Time dilation: a clock moving relative to an observer is measured by that observer to run slower (tick less frequently) than an identical clock at rest with them.", "Length contraction: an object moving relative to an observer is measured by that observer to be shorter along its direction of motion than it would be measured in its own rest frame.", "Both effects only become noticeable at speeds that are a significant fraction of c, and both are required precisely because c itself cannot change between frames."]}, {"id": "4.1.1.7", "unit": 4, "topic": "T1 - Special Relativity", "subtopic": "S1 - Special Relativity", "code": "4.1.1.7", "descriptor": "Describe the concepts of time dilation, proper time interval, relativistic time interval, length contraction, proper length, relativistic length, rest mass and relativistic momentum.", "graphical": false, "needsExplanation": true, "modelAnswer": ["Time dilation: the effect by which the time interval between two events, as measured by an observer in relative motion to those events, is longer (dilated) than the interval measured by an observer for whom the events occur at the same location.", "Proper time interval (Δt₀): the time between two events as measured by an observer at rest relative to both events (i.e. both events happen at the same point in that observer's frame) — the shortest possible measured interval between the two events.", "Relativistic time interval (Δt): the longer time between the same two events as measured by an observer moving relative to the frame in which the events occur at the same place; Δt = γΔt₀, where γ = 1/√(1 − v²/c²).", "Length contraction: the effect by which an object's measured length, as judged by an observer moving relative to it, is shorter than the length measured by an observer at rest relative to the object.", "Proper length (L₀): the length of an object as measured in the frame in which the object is at rest — the largest length any observer will measure.", "Relativistic length (L): the shorter length measured by an observer moving relative to the object; L = L₀/γ.", "Rest mass (m₀): the mass of an object as measured in its own rest frame — an invariant property of the object, the same for all observers.", "Relativistic momentum: p = γm₀v, which grows faster than the classical p = m₀v as v increases, diverging sharply as v approaches c."]}, {"id": "4.1.1.8", "unit": 4, "topic": "T1 - Special Relativity", "subtopic": "S1 - Special Relativity", "code": "4.1.1.8", "descriptor": "Describe the phenomena of time dilation and length contraction, including examples of experimental evidence of the phenomena.", "graphical": false, "needsExplanation": true, "modelAnswer": ["Time dilation and length contraction both follow directly from requiring the speed of light to be constant for every inertial observer; both are quantified by the Lorentz factor γ = 1/√(1 − v²/c²), and both become significant only as v approaches c.", "Muon decay experiments provide evidence: many more muons are detected at sea level than the muon's proper (rest-frame) lifetime would allow for classically, consistent with their decay clock being time-dilated as measured from Earth.", "Precise atomic clock experiments (e.g. the Hafele–Keating experiment) show clocks flown on fast-moving aircraft accumulate a measurably different amount of time than identical clocks left on the ground, matching relativistic predictions to high accuracy.", "Particle accelerator data (e.g. particle lifetimes and momenta measured at high speed) also consistently matches relativistic predictions rather than classical ones, providing further independent confirmation."]}, {"id": "4.1.1.9", "unit": 4, "topic": "T1 - Special Relativity", "subtopic": "S1 - Special Relativity", "code": "4.1.1.9", "descriptor": "State the mass–energy equivalence relationship.", "graphical": false, "needsExplanation": true, "modelAnswer": ["Mass–energy equivalence: E = mc², where E is energy, m is mass, and c is the speed of light in a vacuum.", "It states mass and energy are equivalent, interchangeable forms of the same underlying physical quantity: any object with mass has an associated 'rest energy' (E₀ = m₀c²), and conversely any store of energy has an associated equivalent mass.", "Because c² is an extremely large number, even a small mass corresponds to an enormous quantity of energy — this underlies processes such as nuclear fission/fusion and particle-antiparticle annihilation, where measurable amounts of mass are converted directly into energy (or vice versa)."]}, {"id": "4.1.1.10", "unit": 4, "topic": "T1 - Special Relativity", "subtopic": "S1 - Special Relativity", "code": "4.1.1.10", "descriptor": "Solve problems involving time dilations, length contraction and relativistic momentum using  equations on RHS", "graphical": true, "needsExplanation": false, "modelAnswer": null}, {"id": "4.1.1.11", "unit": 4, "topic": "T1 - Special Relativity", "subtopic": "S1 - Special Relativity", "code": "4.1.1.11", "descriptor": "Explain the implications of relativistic momentum of objects increasing as they approach the speed of light.", "graphical": false, "needsExplanation": true, "modelAnswer": ["As an object's speed approaches c, its relativistic momentum p = γm₀v grows increasingly steeply, since the Lorentz factor γ → ∞ as v → c.", "Correspondingly larger amounts of energy input are needed to produce each further increase in speed as v gets closer to c, with the energy required diverging toward infinity as v → c.", "Because an infinite amount of energy would be required to accelerate a massive object to exactly the speed of light, massive objects can approach but never reach or exceed c.", "At high speed, additional energy input predominantly increases the object's momentum/relativistic energy rather than producing a proportionate increase in speed, in contrast to the classical (Newtonian) case where they increase together via p = mv."]}, {"id": "4.1.1.12", "unit": 4, "topic": "T1 - Special Relativity", "subtopic": "S1 - Special Relativity", "code": "4.1.1.12", "descriptor": "Explain paradoxical scenarios that may arise as a result of special relativity including the twins’ paradox, flashlights on a train, and the ladder in the barn paradox.", "graphical": false, "needsExplanation": true, "modelAnswer": ["Twins' paradox: one twin travels away and back at relativistic speed while the other remains on Earth; time dilation means the travelling twin experiences less elapsed proper time and is younger on return. The apparent paradox (each twin could argue the other is the one 'moving') is resolved because the travelling twin's frame is non-inertial — they must decelerate and accelerate to turn around — breaking the symmetry between the two frames, so the situation is not actually reciprocal.", "Flashlights on a train: light is emitted simultaneously from each end of a moving train, toward its centre. An observer on the train (equidistant from both ends in their own frame) measures the light arriving simultaneously, but an observer on the ground measures it arriving at different times, because the train (and its midpoint) moves toward one flash and away from the other during the light's travel time. This illustrates the relativity of simultaneity rather than a contradiction.", "Ladder (pole) in the barn: a ladder longer than a barn, moving fast enough, is measured (via length contraction) to fit entirely inside the barn at one instant, in the barn's rest frame; in the ladder's own rest frame, however, it is the barn that is contracted, so the ladder never fully fits. Both descriptions are consistent once the relativity of simultaneity is taken into account — 'both doors closed at once' is not a frame-independent statement."]}, {"id": "4.2.2.1", "unit": 4, "topic": "T2 - Quantum theory", "subtopic": "S2 - Quantum Theory", "code": "4.2.2.1", "descriptor": "Explain how the double slit experiment provides evidence for the wave model of light.", "graphical": false, "needsExplanation": true, "modelAnswer": ["When light passes through two closely-spaced narrow slits, it produces a repeating pattern of alternating bright and dark fringes on a screen placed behind them.", "This pattern occurs because light spreads out (diffracts) after each slit, so light from the two slits overlaps on the screen and can interfere; at each point on the screen, the two overlapping waves have travelled slightly different distances from the two slits.", "Where this path difference is a whole number of wavelengths, the two waves arrive in phase and interfere constructively, producing a bright fringe; where the path difference is a half-integer number of wavelengths, the waves arrive out of phase and interfere destructively, producing a dark fringe.", "Since interference (and the diffraction that enables it) only occurs for waves overlapping and superposing, and since the measured fringe spacing matches the quantitative predictions of wave theory (based on slit separation, screen distance and wavelength), the pattern is direct evidence that light is behaving as a wave when it passes through the slits."]}, {"id": "4.2.2.2", "unit": 4, "topic": "T2 - Quantum theory", "subtopic": "S2 - Quantum Theory", "code": "4.2.2.2", "descriptor": "Describe light as an electromagnetic wave.", "graphical": false, "needsExplanation": true, "modelAnswer": ["Light is a transverse electromagnetic wave, made up of oscillating electric and magnetic fields perpendicular to each other and to the direction of travel.", "It requires no medium and travels through a vacuum at speed c; it obeys the wave relationship c = fλ, linking its frequency and wavelength.", "Visible light occupies a narrow band of wavelengths/frequencies within the much broader electromagnetic spectrum, with different wavelengths within that band perceived as different colours."]}, {"id": "4.2.2.3", "unit": 4, "topic": "T2 - Quantum theory", "subtopic": "S2 - Quantum Theory", "code": "4.2.2.3", "descriptor": "Explain the concept of black-body radiation and the significance of the evidence it provides.", "graphical": false, "needsExplanation": true, "modelAnswer": ["Black-body radiation is the electromagnetic radiation emitted by an idealised object (a black body) that absorbs all incident radiation and re-emits energy across a continuous spectrum of wavelengths, with the shape and peak of that spectrum depending only on temperature.", "Classical (wave-based) physics treated the emitted energy as continuously variable, and this predicted that the intensity of emitted radiation should increase without limit as wavelength decreases (the 'ultraviolet catastrophe'); but measured black-body spectra instead rise to a peak at a temperature-dependent wavelength and then fall away at shorter wavelengths, directly contradicting this classical prediction.", "Planck resolved this discrepancy by proposing that energy is emitted and absorbed only in discrete packets (quanta), each of energy E = hf, rather than continuously; because only whole numbers of these energy packets can be emitted, very high-frequency (short-wavelength) emission becomes statistically unlikely, which is exactly what removes the ultraviolet catastrophe and produces a formula matching the observed spectrum closely across all wavelengths and temperatures.", "Because this quantisation assumption was the only way to explain the observed spectrum, the success of Planck's model was the first strong evidence that energy is quantised, and it directly seeded the later development of the photon model of light and quantum theory more broadly."]}, {"id": "4.2.2.4", "unit": 4, "topic": "T2 - Quantum theory", "subtopic": "S2 - Quantum Theory", "code": "4.2.2.4", "descriptor": "Describe the photoelectric effect in terms of the photon.", "graphical": false, "needsExplanation": true, "modelAnswer": ["The photoelectric effect is the emission of electrons from a metal surface when light of sufficiently high frequency is incident on it.", "In this model, light is treated as a stream of discrete energy packets called photons, each carrying energy E = hf, where h is Planck's constant and f is the light's frequency.", "A single photon interacts with (and transfers all of its energy to) a single electron in the metal; if that energy is enough to overcome the metal's work function (the minimum energy binding the electron to the surface), the electron is emitted.", "Any photon energy in excess of the work function becomes the emitted electron's kinetic energy: Ek(max) = hf − φ.", "Electron emission occurs effectively instantaneously once a photon of sufficient energy arrives, and the number of electrons emitted per second (not their individual energy) depends on light intensity — both features match the photon model but are difficult to explain with a purely wave-based model of light."]}, {"id": "4.2.2.5", "unit": 4, "topic": "T2 - Quantum theory", "subtopic": "S2 - Quantum Theory", "code": "4.2.2.5", "descriptor": "Describe the concepts of threshold frequency and work function.", "graphical": false, "needsExplanation": true, "modelAnswer": ["Threshold frequency (f₀): the minimum frequency of incident light capable of ejecting electrons from a given metal's surface; below f₀, no electrons are emitted no matter how intense the light is, since no single photon carries enough energy.", "Work function (φ): the minimum energy needed to remove an electron from a particular metal's surface, related to the threshold frequency by φ = hf₀.", "Different metals have different work functions (and therefore different threshold frequencies), reflecting how strongly each metal binds its surface electrons."]}, {"id": "4.2.2.6", "unit": 4, "topic": "T2 - Quantum theory", "subtopic": "S2 - Quantum Theory", "code": "4.2.2.6", "descriptor": "Solve problems involving blackbody radiation and the photoelectric effect using equations on RHS", "graphical": true, "needsExplanation": false, "modelAnswer": null}, {"id": "4.2.2.7", "unit": 4, "topic": "T2 - Quantum theory", "subtopic": "S2 - Quantum Theory", "code": "4.2.2.7", "descriptor": "Compare the different models of the atom proposed by Rutherford and Bohr.", "graphical": false, "needsExplanation": true, "modelAnswer": ["Rutherford's model: based on alpha-particle scattering evidence, describes the atom as a small, dense, positively charged nucleus at the centre, with electrons existing in the mostly empty space around it — but classically, orbiting (accelerating) electrons should continuously radiate energy and spiral into the nucleus, and the model gives no explanation for the discrete line spectra observed for atoms.", "Bohr's model: retains Rutherford's central nucleus, but adds the postulate that electrons can only occupy specific, quantised, stable orbits (energy levels) in which they do not radiate energy; electrons emit or absorb a photon of energy E = hf only when transitioning between these fixed levels.", "Bohr's quantisation successfully explains why atoms emit and absorb only discrete frequencies of light (the line spectrum), directly addressing the two features Rutherford's model could not account for.", "Both models retain the same basic nuclear structure (a small positive nucleus with orbiting electrons); Bohr's contribution was specifically the quantisation of electron energy levels."]}, {"id": "4.2.2.8", "unit": 4, "topic": "T2 - Quantum theory", "subtopic": "S2 - Quantum Theory", "code": "4.2.2.8", "descriptor": "Explain how Bohr’s model of the hydrogen atom integrates light quanta and atomic energy states to explain the specific wavelengths in the hydrogen line spectrum.", "graphical": false, "needsExplanation": true, "modelAnswer": ["Bohr's model restricts electrons in the hydrogen atom to a discrete set of quantised, stable energy levels around the nucleus.", "When an electron moves from a higher energy level to a lower one, it emits a single photon whose energy equals exactly the difference between the two levels: Ephoton = Ei − Ef = hf.", "Because only specific energy-level differences are possible in the atom, only specific photon energies (and therefore specific frequencies/wavelengths) can be emitted, which is exactly what produces the observed discrete, characteristic line spectrum of hydrogen rather than a continuous range of colours.", "The same logic in reverse explains hydrogen's absorption spectrum: only photons with energy matching a possible transition are absorbed, promoting an electron to a higher level."]}, {"id": "4.2.2.9", "unit": 4, "topic": "T2 - Quantum theory", "subtopic": "S2 - Quantum Theory", "code": "4.2.2.9", "descriptor": "Solve problems involving the line spectra of simple atoms using atomic energy states or atomic energy level diagrams using equations on RHS", "graphical": true, "needsExplanation": false, "modelAnswer": null}, {"id": "4.2.2.10", "unit": 4, "topic": "T2 - Quantum theory", "subtopic": "S2 - Quantum Theory", "code": "4.2.2.10", "descriptor": "Describe wave–particle duality of light by identifying evidence that supports the wave characteristics of light and evidence that supports the particle characteristics of light.", "graphical": false, "needsExplanation": true, "modelAnswer": ["Evidence supporting the wave model: interference (e.g. the double-slit fringe pattern) and diffraction, both of which require light to spread out from a source/aperture and overlap with itself — behaviour unique to waves.", "Evidence supporting the particle model: the photoelectric effect, where light must transfer energy in discrete photon packets (E = hf) — shown by the existence of a threshold frequency and by emitted electrons' kinetic energy depending on frequency, not intensity.", "Wave–particle duality is the conclusion that light exhibits both wave-like and particle-like behaviour depending on the situation/experiment; each model successfully explains a different set of phenomena, and a complete description of light draws on both."]}, {"id": "4.2.2.11", "unit": 4, "topic": "T2 - Quantum theory", "subtopic": "S2 - Quantum Theory", "code": "4.2.2.11", "descriptor": "Interpret data related to the photoelectric effect.", "graphical": true, "needsExplanation": true, "modelAnswer": ["Identify the variables typically plotted (e.g. maximum kinetic energy of emitted electrons vs frequency of incident light) and describe the relationship shown — linear once frequency exceeds the threshold frequency, and zero (no emission) below it.", "Use the x-intercept of the linear region to read off the threshold frequency f₀ for that metal, and use the gradient of the line to determine Planck's constant h, since Ek(max) = hf − φ has gradient h.", "Use the y-intercept (or the value hf₀) to determine the work function φ of the metal being tested.", "Relate the linear shape of the graph directly to Einstein's photoelectric equation, and comment on the reliability of extracted values (line of best fit, scatter, extrapolation beyond measured data)."]}, {"id": "4.3.1.1", "unit": 4, "topic": "T3 - Standard Model", "subtopic": "S1 - The Standard Model", "code": "4.3.1.1", "descriptor": "Describe the concepts of elementary particles and antiparticles.", "graphical": false, "needsExplanation": true, "modelAnswer": ["Elementary (fundamental) particles are particles with no known internal substructure — they are not composed of any smaller constituent particles (e.g. quarks, leptons, and the gauge bosons).", "Every elementary particle has a corresponding antiparticle, with the same mass but opposite electric charge (and opposite values of other conserved quantum numbers, such as lepton or baryon number).", "When a particle meets its own antiparticle, the pair can annihilate, converting their combined mass entirely into energy (commonly as photons), in accordance with E = mc².", "The reverse process, pair production, can also occur: a sufficiently energetic photon can convert into a particle–antiparticle pair, again consistent with E = mc²."]}, {"id": "4.3.1.2", "unit": 4, "topic": "T3 - Standard Model", "subtopic": "S1 - The Standard Model", "code": "4.3.1.2", "descriptor": "Identify the six types of quarks.", "graphical": false, "needsExplanation": true, "modelAnswer": ["The six quark flavours: up, down, charm, strange, top, bottom.", "Up, charm and top carry charge +⅔e; down, strange and bottom carry charge −⅓e.", "Quarks are grouped into three generations by increasing mass: (up, down), (charm, strange), (top, bottom)."]}, {"id": "4.3.1.3", "unit": 4, "topic": "T3 - Standard Model", "subtopic": "S1 - The Standard Model", "code": "4.3.1.3", "descriptor": "Describe baryons and mesons.", "graphical": false, "needsExplanation": true, "modelAnswer": ["Baryons are composite particles made of three quarks bound together (e.g. the proton = uud, the neutron = udd).", "Mesons are composite particles made of one quark and one antiquark bound together (e.g. pions, made of a quark-antiquark pair).", "Both baryons and mesons are classified as hadrons — particles built from quarks, held together by the strong nuclear force (via gluon exchange)."]}, {"id": "4.3.1.4", "unit": 4, "topic": "T3 - Standard Model", "subtopic": "S1 - The Standard Model", "code": "4.3.1.4", "descriptor": "Identify the six types of leptons.", "graphical": false, "needsExplanation": true, "modelAnswer": ["The six lepton flavours: electron, muon, tau, electron neutrino, muon neutrino, tau neutrino.", "The electron, muon and tau each carry charge −1e; the three corresponding neutrinos are electrically neutral.", "Like quarks, leptons are grouped into three generations by increasing mass: (electron, electron neutrino), (muon, muon neutrino), (tau, tau neutrino)."]}, {"id": "4.3.1.5", "unit": 4, "topic": "T3 - Standard Model", "subtopic": "S1 - The Standard Model", "code": "4.3.1.5", "descriptor": "Identify the four gauge bosons.", "graphical": false, "needsExplanation": true, "modelAnswer": ["The four gauge bosons: the photon (carries the electromagnetic force), the gluon (carries the strong nuclear force), and the W and Z bosons (carry the weak nuclear force).", "The graviton, a hypothesised carrier of the gravitational force, is not part of the confirmed Standard Model, since gravity is not yet successfully incorporated into it."]}, {"id": "4.3.1.6", "unit": 4, "topic": "T3 - Standard Model", "subtopic": "S1 - The Standard Model", "code": "4.3.1.6", "descriptor": "Compare the strong nuclear, weak nuclear and electromagnetic forces in terms of the gauge bosons.", "graphical": false, "needsExplanation": true, "modelAnswer": ["Strong nuclear force: carried by gluons (massless); acts directly between quarks (binding them into hadrons) and indirectly binds protons and neutrons together in the nucleus; very strong at short range (~10⁻¹⁵ m) but negligible beyond that range.", "Weak nuclear force: carried by the massive W⁺, W⁻ and Z bosons; responsible for processes such as beta decay, where it changes one quark flavour into another; acts over an extremely short range and is weaker in effective strength than the strong force at comparable distances.", "Electromagnetic force: carried by the massless photon; acts between all electrically charged particles over an unlimited (infinite) range, but is weaker than the strong force at typical nuclear distances.", "The relative range of each force is linked to the mass of its carrier boson: massless carriers (gluon, photon) allow forces that can act over long or infinite range, while the large mass of the W/Z bosons is what confines the weak force to an extremely short range."]}, {"id": "4.3.1.7", "unit": 4, "topic": "T3 - Standard Model", "subtopic": "S1 - The Standard Model", "code": "4.3.1.7", "descriptor": "Contrast the fundamental forces experienced by quarks and leptons.", "graphical": false, "needsExplanation": true, "modelAnswer": ["Quarks carry colour charge, so they experience the strong nuclear force (via gluon exchange), in addition to the weak nuclear force, the electromagnetic force (since they carry electric charge), and gravity.", "Leptons do not carry colour charge, so charged leptons (electron, muon, tau) experience the weak force, the electromagnetic force, and gravity, but not the strong force.", "Neutrinos carry neither colour charge nor electric charge, so they experience only the weak force and gravity — the most weakly-interacting of the leptons.", "This means quarks are the only elementary particles that experience all four fundamental forces, while leptons never experience the strong force."]}, {"id": "4.3.2.1", "unit": 4, "topic": "T3 - Standard Model", "subtopic": "S2 - Particle Interactions", "code": "4.3.2.1", "descriptor": "Describe the concepts of lepton number and baryon number.", "graphical": false, "needsExplanation": true, "modelAnswer": ["Lepton number: a quantum number assigned as +1 to each lepton, −1 to each antilepton, and 0 to all other particles (quarks, gauge bosons); the total lepton number of an isolated system is conserved in every particle interaction.", "Baryon number: a quantum number assigned as +1 to each baryon, −1 to each antibaryon, and 0 to all other particles (mesons, leptons, gauge bosons); the total baryon number of an isolated system is conserved in every particle interaction.", "These conservation rules can be used to check whether a proposed particle interaction or decay is physically allowed, by comparing the total lepton and baryon numbers before and after."]}, {"id": "4.3.2.2", "unit": 4, "topic": "T3 - Standard Model", "subtopic": "S2 - Particle Interactions", "code": "4.3.2.2", "descriptor": "Solve problems relating to the conservation of lepton number and baryon number in particle interactions using equations on the RHS", "graphical": true, "needsExplanation": false, "modelAnswer": null}, {"id": "4.3.2.3", "unit": 4, "topic": "T3 - Standard Model", "subtopic": "S2 - Particle Interactions", "code": "4.3.2.3", "descriptor": "Describe electron/electron, electron/positron and neutron decay interactions using particle interaction diagrams.", "graphical": false, "needsExplanation": true, "modelAnswer": ["Particle interaction (Feynman-style) diagrams represent particles as directed lines and force-carrying exchange bosons as wavy or dashed lines, typically with time running along one axis and space along the other.", "Electron/electron interaction: two electrons approach and repel one another by exchanging a virtual photon (the electromagnetic interaction); no particles are created or destroyed, and charge, lepton number and energy are each conserved.", "Electron/positron interaction: an electron and its antiparticle, the positron, can annihilate on meeting, converting their combined mass-energy into a pair of photons (or another particle–antiparticle pair); charge sums to zero and lepton number sums to zero both before and after, consistent with conservation.", "Neutron decay (beta-minus decay): a free neutron decays into a proton, an electron and an electron antineutrino (n → p + e⁻ + ν̄e); this is mediated by the weak force, via emission of a virtual W⁻ boson as one down quark inside the neutron converts to an up quark; baryon number, lepton number, charge and energy are each conserved across the decay."]}, {"id": "4.3.2.4", "unit": 4, "topic": "T3 - Standard Model", "subtopic": "S2 - Particle Interactions", "code": "4.3.2.4", "descriptor": "Describe how symmetry in particle interactions occurs to maintain the principles of conservation.", "graphical": false, "needsExplanation": true, "modelAnswer": ["In every particle interaction, quantities such as electric charge, lepton number, baryon number, energy and momentum have equal total values before and after the interaction — they are conserved.", "Symmetry in this context refers to interactions balancing out so these totals match on both sides: for example, a particle and its antiparticle are often created or destroyed together, and decays produce combinations of particles whose quantum numbers sum to the same totals as the original particle.", "Physically observed particle interactions and decays are exactly those combinations that satisfy all of these conservation laws simultaneously — the conservation laws, taken together, determine which processes occur in nature and place clear limits on what is physically possible."]}];
